"""lz-compress: greedy LZ77 over a generated byte buffer (see lz-compress.mi)."""

import sys
import time


def generated_input(n):
    data = bytearray(n)
    size = 0
    state = 11
    while size < n:
        state = state * 48271 % 2147483647
        if size > 64 and state % 4 == 0:
            back = 1 + (state // 4) % 60
            length = 3 + (state // 256) % 20
            k = 0
            while k < length and size < n:
                data[size] = data[size - back]
                size += 1
                k += 1
        else:
            data[size] = 97 + state % 16
            size += 1
    return data


def kernel(n):
    data = generated_input(n)
    size = len(data)
    literals = matches = h = 0
    pos = 0
    while pos < size:
        best_length = best_distance = 0
        for start in range(max(0, pos - 255), pos):
            length = 0
            while pos + length < size and length < 255 and data[start + length] == data[pos + length]:
                length += 1
            if length > best_length:
                best_length = length
                best_distance = pos - start
        if best_length >= 3:
            matches += 1
            h = (h * 31 + best_distance * 256 + best_length) % 1000000007
            pos += best_length
        else:
            literals += 1
            h = (h * 31 + data[pos]) % 1000000007
            pos += 1
    return f"{literals} {matches} {h}"


def run_hot(n):
    expected = kernel(n)
    agree = True
    for _ in range(4):
        checksum = kernel(n)
        agree = agree and checksum == expected
    for _ in range(5):
        start = time.perf_counter_ns()
        checksum = kernel(n)
        elapsed = time.perf_counter_ns() - start
        print(f"hot_ns={elapsed}", file=sys.stderr)
        agree = agree and checksum == expected
    if not agree:
        print("checksum differs between iterations", file=sys.stderr)
        sys.exit(1)
    return expected


def main():
    with open(sys.argv[1]) as f:
        n = int(f.read().strip())
    hot = len(sys.argv) > 2 and sys.argv[2] == "hot"
    print(run_hot(n) if hot else kernel(n))


if __name__ == "__main__":
    main()
